/** 把工具返回体里的 `output` 归一成**可读字符串**（跨进程边界：插件 / MCP / 脚本化工具是运行期
 *  才拿到的，返回 `{ok:true}` / `output:null` / `output:{…}` 都完全可能——`base.ts` 的
 *  `ToolResult.output: string` 约束不到那道边界）。口径：
 *  - 字符串**逐字返回**（含真空串——空串是「真的没输出」这一事实，不许被占位符顶替）；
 *  - 缺失（`undefined`）⇒ 明说没有正文，而不是把字面量 `"undefined"` 当真实输出递给模型；
 *  - `null` / 数字 / 布尔 ⇒ `String(v)`（`"null"` 与缺失分得开）；
 *  - 对象 / 数组 ⇒ JSON（循环引用安全），而不是 `"[object Object]"`；
 *  - 环形 / 带 getter / Proxy 等 `JSON.stringify` 会抛的一类也不许抛（`safeJsonSummary` 兜底）。
 *
 *  **不许抛**：这一格在 loop 的每一次工具返回上都会被调，抛一次就把整轮任务打死。 */
export function readableToolOutput(output: unknown): string {
  if (typeof output === "string") return output;
  if (output === undefined) return "（本工具回执没有正文：output 字段缺失）";
  if (output === null) return "null";
  if (typeof output === "object") {
    const json = safeJsonSummary(output);
    // `JSON.stringify(fn)` / 部分特殊对象会给出 ""：退回 String 也比空着强，但仍不许抛。
    if (json !== "") return json;
    try {
      return String(output);
    } catch {
      return "[无法序列化]";
    }
  }
  return String(output);
}

